// Centralized fetch wrapper for files-mfe.
//
// Adds /api/v1/files prefix, JSON content-type for write methods,
// Idempotency-Key for non-GET writes, credentials: "include" so the
// shell-bff session cookie is sent. Unwraps the {data, error} envelope
// the BFF returns; throws ApiError on failure.
//
// 401 handling: rather than throwing into a blank route, the wrapper
// redirects to the shell-mfe /login page with the user's current URL
// encoded as `return_to` so they land back where they were after
// re-auth. The redirect is suppressed if we're already on /login
// (defensive — prevents loops).
//
// 403 is NOT redirected: it means the session is valid but the user
// lacks permission for this resource. It throws an ApiError (code
// "permission_denied" by default, or whatever code the BFF's error
// envelope supplies) that the calling surface can render directly.

export class ApiError extends Error {
  constructor(
    public readonly status: number,
    public readonly code: string,
    message: string,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

/** Bounce the browser to the shell-mfe login page, preserving the
 *  current URL as `return_to`.
 *
 *  Loop guard: shell-bff's cookie_to_bearer middleware rotates the
 *  refresh token on every request, and /files mount fires ~10
 *  concurrent fetches (useSession, useWorkspaceList, listCorpora,
 *  notifications, etc.). Most lose the race and 401 even though the
 *  user IS authenticated. Each redirect-to-login is a full page
 *  reload, so a module-level latch resets every cycle and produces
 *  an infinite loop. The latch lives in sessionStorage so it
 *  survives page reloads, and bounces back to /login no more than
 *  once per 30s. If the user actually needs to log in again,
 *  /login renders and shell-mfe's AuthProvider catches it; the
 *  cooldown only suppresses the redirect-storm, not the auth state. */
const REDIRECT_KEY = "files-mfe.last-401-redirect-at";
function redirectToLogin(): void {
  if (typeof window === "undefined") return;
  const path = window.location.pathname;
  if (path === "/login" || path.startsWith("/login/")) return;

  let lastAt = 0;
  try {
    const raw = window.sessionStorage.getItem(REDIRECT_KEY);
    if (raw) lastAt = Number.parseInt(raw, 10) || 0;
  } catch {
    // sessionStorage access can throw under hardened CSPs / private mode —
    // fall back to "no recent redirect" and allow the bounce.
  }
  const now = Date.now();
  if (now - lastAt < 30_000) return;
  try {
    window.sessionStorage.setItem(REDIRECT_KEY, String(now));
  } catch {
    // see above
  }
  const returnTo = window.location.pathname + window.location.search;
  window.location.href = `/login?return_to=${encodeURIComponent(returnTo)}`;
}

type EnvelopeOk<T> = { data: T };
type EnvelopeErr = { data: null; error: { code: string; message: string } };
type Envelope<T> = EnvelopeOk<T> | EnvelopeErr;

export interface RequestOptions {
  method?: "GET" | "POST" | "PATCH" | "DELETE";
  body?: unknown;
  query?: Record<string, string | number | boolean>;
}

export async function api<T>(
  path: string,
  opts: RequestOptions = {},
): Promise<T> {
  const method = opts.method ?? "GET";
  const url = buildURL(path, opts.query);
  const headers: Record<string, string> = {
    Accept: "application/json",
  };
  if (opts.body !== undefined) {
    headers["Content-Type"] = "application/json";
  }
  if (method !== "GET") {
    headers["Idempotency-Key"] = crypto.randomUUID();
  }
  const r = await fetch(url, {
    method,
    credentials: "include",
    headers,
    body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
  });

  // Session expired or never existed — bounce to /login. Throw an
  // ApiError too so any caller mid-await sees a consistent error
  // instead of a never-resolving promise; the page unload from the
  // redirect typically arrives first, but the throw is the safety net.
  //
  // 403 is deliberately NOT folded into this branch: it means the
  // caller IS authenticated but lacks permission for this resource.
  // Redirecting to /login would misrepresent an authorization failure
  // as a session expiry. 403 falls through to the normal envelope
  // parsing below so callers get a real, renderable permission error.
  if (r.status === 401) {
    redirectToLogin();
    throw new ApiError(r.status, "unauthenticated", "session expired");
  }

  // Empty-body successful responses (e.g. DELETE → 204 No Content) carry
  // no envelope. Return null cast as T so callers typed as Promise<void>
  // / Promise<null> resolve cleanly without tripping the JSON parser.
  if (r.ok && (r.status === 204 || r.headers.get("Content-Length") === "0")) {
    return null as T;
  }

  // Read the body text once so a trailing empty body on a non-204 OK
  // response degrades gracefully to "no envelope".
  const text = await r.text();
  let envelope: Envelope<T> | null = null;
  if (text.length > 0) {
    try {
      envelope = JSON.parse(text) as Envelope<T>;
    } catch {
      if (!r.ok) {
        throw new ApiError(r.status, "unknown", `request failed: ${r.status}`);
      }
      throw new ApiError(r.status, "unknown", "non-JSON response");
    }
  } else if (r.ok) {
    return null as T;
  }
  if (!r.ok) {
    if (envelope && "error" in envelope && envelope.error) {
      throw new ApiError(r.status, envelope.error.code, envelope.error.message);
    }
    // No envelope on a 403 (e.g. a proxy-level block) — still give callers
    // a distinct, non-"unknown" code so they can render a real permission
    // message rather than a generic failure.
    if (r.status === 403) {
      throw new ApiError(
        r.status,
        "permission_denied",
        "you do not have permission to perform this action",
      );
    }
    throw new ApiError(r.status, "unknown", `request failed: ${r.status}`);
  }
  if (envelope && "data" in envelope) {
    return envelope.data as T;
  }
  throw new ApiError(r.status, "malformed_envelope", "missing data field");
}

function buildURL(
  path: string,
  query?: Record<string, string | number | boolean>,
): string {
  const url = new URL(
    path.startsWith("/api/v1/") ? path : `/api/v1/files${path}`,
    window.location.origin,
  );
  if (query) {
    for (const [k, v] of Object.entries(query)) {
      url.searchParams.set(k, String(v));
    }
  }
  return url.pathname + url.search;
}


