import { api } from "./client";
import type { Edge } from "./edges";
import type { Entity } from "./entities";

export type CorpusVisibility = "PRIVATE" | "TEAM";

export interface Corpus {
  id: string;
  org_id: string;
  name: string;
  description: string;
  visibility: CorpusVisibility;
  is_personal_inbox?: boolean;
  doc_count?: number;
  created_by: string;
  created_at: string;
  legacy_id?: string;
}

export interface CreateCorpusRequest {
  name: string;
  description?: string;
  visibility?: CorpusVisibility;
}

export interface UpdateCorpusRequest {
  name?: string;
  description?: string;
  visibility?: CorpusVisibility;
}

export interface ListCorporaResponse {
  corpora: Corpus[];
  next_cursor: string;
}

export async function createCorpus(req: CreateCorpusRequest): Promise<Corpus> {
  return api<Corpus>("/corpora", { method: "POST", body: req });
}

export async function getCorpus(id: string): Promise<Corpus> {
  return api<Corpus>(`/corpora/${id}`);
}

export async function listCorpora(
  cursor = "",
  limit = 50,
  includeDocCount = false,
): Promise<ListCorporaResponse> {
  const query: Record<string, string | number> = { cursor, limit };
  if (includeDocCount) query.include_doc_count = "true";
  return api<ListCorporaResponse>("/corpora", { query });
}

export async function listWorkspaceCorpora(): Promise<ListCorporaResponse> {
  return api<ListCorporaResponse>("/workspace/corpora");
}

export async function updateCorpus(
  id: string,
  req: UpdateCorpusRequest,
): Promise<Corpus> {
  return api<Corpus>(`/corpora/${id}`, { method: "PATCH", body: req });
}

export async function deleteCorpus(id: string): Promise<void> {
  await api<null>(`/corpora/${id}`, { method: "DELETE" });
}

export interface CorpusSubgraphResponse {
  entities: Entity[];
  edges: Edge[];
  next_cursor: string;
}

export interface CorpusSubgraphOptions {
  limit?: number;
  cursor?: string;
}

export async function getCorpusSubgraph(
  corpusId: string,
  opts: CorpusSubgraphOptions = {},
): Promise<CorpusSubgraphResponse> {
  const query: Record<string, string | number> = {};
  if (opts.limit) query.limit = opts.limit;
  if (opts.cursor) query.cursor = opts.cursor;
  return api<CorpusSubgraphResponse>(`/corpora/${corpusId}/subgraph`, {
    query,
  });
}


