import { api, ApiError } from "./client";
import type { OrphanCandidate } from "./folders";

export interface PreviewPurgeResponse {
  would_orphan: OrphanCandidate[];
}

export interface PurgeResponse {
  chunks_removed: number;
  qdrant_points_removed: number;
  entities_removed: number;
  edges_removed: number;
  minio_cleanup_succeeded: boolean;
}

export interface IngestJob {
  id: string;
  org_id: string;
  document_id: string;
  status:
    | "pending"
    | "parsing"
    | "embedding"
    | "extracting"
    | "indexing"
    | "complete"
    | "failed";
  error?: string;
  created_at: string;
  started_at?: string;
  completed_at?: string;
}

export interface FilesDocument {
  id: string;
  org_id: string;
  corpus_id: string;
  folder_id?: string;
  filename: string;
  mime_type: string;
  size_bytes: number;
  minio_object: string;
  uploaded_by: string;
  uploaded_at: string;
  legacy_id?: string;
  /**
   * Current pipeline status of the document's most recent ingest_job,
   * LEFT-joined into Get/List/Upload responses by files-svc.
   *
   * One of: "pending" | "parsing" | "embedding" | "extracting"
   *         | "indexing" | "complete" | "failed"
   *
   * Empty/undefined when no ingest_job exists yet (rare: legacy
   * migrator-imported rows from before ingest was wired).
   */
  ingest_status?: string;
  /**
   * Set when the ingest worker recognised this document's CONTENT as a
   * platform domain object rather than opaque prose (#256).
   *
   * One of: "audience_profile" | "character_set" | "exercise"
   *
   * Absent for the overwhelmingly common case — an ordinary document, or one
   * ingested before detection shipped. Typed as a plain string rather than
   * the KnownType union because it arrives from the wire: a newer files-svc
   * may stamp a type this build has no mapping for, and narrowing happens at
   * the render seam (normalizeKnownType) instead.
   */
  known_type?: string;
}

export interface UploadDocumentResponse {
  document: FilesDocument;
  ingest_job_id: string;
}

export interface ListDocumentsResponse {
  documents: FilesDocument[];
  next_cursor: string;
}

export interface UploadProgressEvent {
  loaded: number;
  total: number;
}

export interface UploadOptions {
  folderId?: string;
  onProgress?: (e: UploadProgressEvent) => void;
  signal?: AbortSignal;
}

/**
 * Turn one finished XHR into an ApiError.
 *
 * The upload path is the only place in this MFE that talks to the BFF without
 * going through `api()`, so it is also the only place that has to cope with a
 * response the platform envelope never produced. Two of those matter:
 *
 * - **nginx rejects the body itself.** An over-cap upload never reaches a BFF;
 *   nginx answers 413 with its own HTML error page. `JSON.parse` throws, and
 *   the previous code let the envelope stay `null` and fell through to the
 *   generic `upload failed: 413` — a string naming neither the file nor the
 *   reason, which is half of why an oversized upload looked like nothing
 *   happening at all (#2754).
 * - **any proxy hop 502s.** Same shape, different status.
 *
 * So the status is mapped to a code when the body can't supply one, and the
 * result is always an ApiError — structured, so callers branch on `status` /
 * `code` instead of matching English.
 */
function uploadFailure(status: number, responseText: string): ApiError {
  let envelope: { error?: { code?: string; message?: string } } | null = null;
  try {
    envelope = responseText ? JSON.parse(responseText) : null;
  } catch {
    // Not the platform envelope — an edge-generated HTML page, or a truncated
    // body. Fall through to the status-derived mapping below.
  }

  const fallbackCode =
    status === 413
      ? "request_too_large"
      : status >= 500
        ? "upstream_error"
        : "upload_failed";

  return new ApiError(
    status,
    envelope?.error?.code ?? fallbackCode,
    envelope?.error?.message ?? `upload failed: ${status}`,
  );
}

export async function uploadDocument(
  corpusId: string,
  file: File,
  opts: UploadOptions = {},
): Promise<UploadDocumentResponse> {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    const params = new URLSearchParams();
    if (opts.folderId) params.set("folder_id", opts.folderId);
    const qs = params.toString() ? `?${params.toString()}` : "";

    xhr.open("POST", `/api/v1/files/corpora/${corpusId}/documents${qs}`);
    xhr.withCredentials = true;
    xhr.setRequestHeader("Idempotency-Key", crypto.randomUUID());

    xhr.upload.onprogress = (e) => {
      if (e.lengthComputable && opts.onProgress) {
        opts.onProgress({ loaded: e.loaded, total: e.total });
      }
    };
    xhr.onload = () => {
      if (xhr.status >= 200 && xhr.status < 300) {
        let env: { data?: UploadDocumentResponse } | null = null;
        try {
          env = xhr.responseText ? JSON.parse(xhr.responseText) : null;
        } catch {
          // A 2xx we cannot parse is still a failure: there is no document id
          // to hand back, so resolving would report a phantom success.
        }
        if (env?.data) {
          resolve(env.data);
          return;
        }
      }
      reject(uploadFailure(xhr.status, xhr.responseText));
    };
    xhr.onerror = () =>
      reject(new ApiError(0, "network_error", "upload network error"));
    xhr.onabort = () => reject(new ApiError(0, "upload_aborted", "upload aborted"));
    opts.signal?.addEventListener("abort", () => xhr.abort());

    const fd = new FormData();
    fd.append("file", file);
    xhr.send(fd);
  });
}

export async function listDocuments(
  corpusId: string,
  opts: {
    limit?: number;
    cursor?: string;
    query?: string;
    /**
     * Folder filter. Omitted = corpus root only (`folder_id IS NULL`
     * on the server). Set to a folder id to scope the list to that
     * folder. The server has no "all folders" mode — to list every
     * document regardless of folder, call once per folder.
     */
    folderId?: string;
  } = {},
): Promise<ListDocumentsResponse> {
  const query: Record<string, string | number> = {};
  if (opts.limit) query.limit = opts.limit;
  if (opts.cursor) query.cursor = opts.cursor;
  if (opts.query) query.q = opts.query;
  if (opts.folderId) query.folder_id = opts.folderId;
  return api<ListDocumentsResponse>(`/corpora/${corpusId}/documents`, {
    query,
  });
}

export async function getDocument(id: string): Promise<FilesDocument> {
  return api<FilesDocument>(`/documents/${id}`);
}

export async function deleteDocument(id: string): Promise<void> {
  await api<null>(`/documents/${id}`, { method: "DELETE" });
}

export async function getJobStatus(jobId: string): Promise<IngestJob> {
  return api<IngestJob>(`/ingest-jobs/${jobId}`);
}

export async function retryIngestJob(jobId: string): Promise<IngestJob> {
  return api<IngestJob>(`/ingest-jobs/${jobId}/retry`, { method: "POST" });
}

export async function previewPurgeDocument(opts: {
  corpusId: string;
  docId: string;
}): Promise<PreviewPurgeResponse> {
  return api<PreviewPurgeResponse>(
    `/api/v1/files/corpora/${opts.corpusId}/documents/${opts.docId}:preview-purge`,
    { method: "POST" },
  );
}

export async function trashDocument(opts: {
  corpusId: string;
  docId: string;
}): Promise<FilesDocument> {
  return api<FilesDocument>(
    `/api/v1/files/corpora/${opts.corpusId}/documents/${opts.docId}:trash`,
    { method: "POST" },
  );
}

export async function restoreDocument(opts: {
  corpusId: string;
  docId: string;
}): Promise<FilesDocument> {
  return api<FilesDocument>(
    `/api/v1/files/corpora/${opts.corpusId}/documents/${opts.docId}:restore`,
    { method: "POST" },
  );
}

export async function purgeDocument(opts: {
  corpusId: string;
  docId: string;
}): Promise<PurgeResponse> {
  // Use raw fetch here so we can inspect the status before the api() helper
  // discards non-envelope 4xx responses. The 409 "would_orphan" path returns
  // a non-standard body { orphans: [...] } that must be preserved for
  // PurgeConfirmModal to read.
  const url = `/api/v1/files/corpora/${opts.corpusId}/documents/${opts.docId}:purge`;
  const res = await fetch(url, {
    method: "POST",
    credentials: "include",
    headers: {
      Accept: "application/json",
      "Idempotency-Key": crypto.randomUUID(),
    },
  });
  if (res.status === 409) {
    const body = (await res.json()) as { orphans?: unknown };
    const err = new Error("would_orphan") as Error & { orphans?: unknown };
    err.orphans = body.orphans;
    throw err;
  }
  if (!res.ok) {
    throw new Error(`purge failed: ${res.status}`);
  }
  const body = (await res.json()) as { data: PurgeResponse };
  return body.data;
}

export async function moveDocument(
  documentId: string,
  targetFolderId?: string,
): Promise<FilesDocument> {
  return api<FilesDocument>(`/documents/${documentId}:move`, {
    method: "POST",
    body: { target_folder_id: targetFolderId },
  });
}

export async function renameDocument(
  documentId: string,
  filename: string,
): Promise<FilesDocument> {
  return api<FilesDocument>(`/documents/${documentId}:rename`, {
    method: "POST",
    body: { filename },
  });
}

export async function copyDocument(documentId: string): Promise<FilesDocument> {
  return api<FilesDocument>(`/documents/${documentId}:copy`, { method: "POST" });
}

/**
 * Fetch the raw bytes of a document as a Blob.
 * Uses credentials:"include" (cookie auth, same as uploadDocument/purgeDocument).
 * Pass disposition:"attachment" to trigger a Content-Disposition: attachment header
 * on the server response (for browser download).
 */
export async function fetchDocumentBlob(
  documentId: string,
  disposition: "inline" | "attachment" = "inline",
): Promise<Blob> {
  const qs = disposition === "attachment" ? "?disposition=attachment" : "";
  const res = await fetch(`/api/v1/files/documents/${documentId}/raw${qs}`, {
    credentials: "include",
    headers: { Accept: "*/*" },
  });
  if (!res.ok) {
    throw new Error(`raw fetch failed: ${res.status}`);
  }
  return res.blob();
}


