import { api } from "./client";
import type { Entity } from "./entities";
import type { ProvenanceEntry } from "./entities";

export interface Edge {
  id: string;
  org_id: string;
  type_id: string;
  source_id: string;
  target_id: string;
  properties: Record<string, unknown>;
  created_at: string;
  updated_at?: string;
  legacy_id?: string;
}

export interface AddEdgeRequest {
  type_id: string;
  source_id: string;
  target_id: string;
  properties?: Record<string, unknown>;
}

export async function addEdge(req: AddEdgeRequest): Promise<Edge> {
  return api<Edge>("/edges", { method: "POST", body: req });
}

export async function getEdge(id: string): Promise<Edge> {
  return api<Edge>(`/edges/${id}`);
}

export async function removeEdge(id: string): Promise<void> {
  await api<null>(`/edges/${id}`, { method: "DELETE" });
}

export interface UpdateEdgeRequest {
  /** Optional new relationship_types.id. Omit to leave unchanged. */
  type_id?: string;
  /** Optional replacement properties (REPLACE semantics). Omit to leave unchanged. */
  properties?: Record<string, unknown>;
}

export async function updateEdge(
  id: string,
  req: UpdateEdgeRequest,
): Promise<Edge> {
  return api<Edge>(`/edges/${id}`, { method: "PATCH", body: req });
}

export interface NeighborhoodResponse {
  seed: Entity;
  entities: Entity[];
  edges: Edge[];
}

export interface NeighborhoodOptions {
  depth?: number;
  limit?: number;
  edgeTypeIds?: string[];
  entityTypeIds?: string[];
}

// ---------------------------------------------------------------------------
// Edge provenance
// ---------------------------------------------------------------------------

export interface GetEdgeProvenanceResponse {
  provenance: ProvenanceEntry[];
}

/**
 * Fetch source-chunk provenance for a relationship edge.
 *
 * TODO(PR-E): Wire to the real files-svc `GetEdgeProvenance` RPC once
 * the backend endpoint ships. The BFF route will be `GET /edges/:id/provenance`.
 * For now returns an empty list so the UI renders the "No source provenance yet."
 * empty-state per files.md §11.2.
 */
export async function getEdgeProvenance(
  _id: string,
): Promise<GetEdgeProvenanceResponse> {
  return { provenance: [] };
}

// ---------------------------------------------------------------------------
// Edge audit
// ---------------------------------------------------------------------------

export interface AuditEvent {
  id: string;
  /** Actor who triggered the event (user id or service account). */
  actor: string;
  /** ISO 8601 timestamp. */
  timestamp: string;
  /** Audit event slug, e.g. "files.edge.added" or "audit.files.edge.added". */
  event_slug: string;
  /** Optional request id propagated from the original RPC headers. */
  request_id?: string;
}

export interface GetEdgeAuditResponse {
  audit_events: AuditEvent[];
}

interface AuditEntryEnvelope {
  event_id: string;
  action: string;
  actor: string;
  occurred_at: string;
  request_id?: string;
}

interface AuditEnvelope {
  entries: AuditEntryEnvelope[];
}

function adaptAuditEntries(env: AuditEnvelope): AuditEvent[] {
  return env.entries.map((e) => ({
    id: e.event_id,
    actor: e.actor,
    timestamp: e.occurred_at,
    event_slug: e.action,
    request_id: e.request_id,
  }));
}

/** Fetch the audit-event log for a relationship edge. */
export async function getEdgeAudit(id: string): Promise<GetEdgeAuditResponse> {
  const env = await api<AuditEnvelope>(`/edges/${id}/audit`);
  return { audit_events: adaptAuditEntries(env) };
}

export async function getNeighborhood(
  seedId: string,
  opts: NeighborhoodOptions = {},
): Promise<NeighborhoodResponse> {
  const query: Record<string, string | number> = {};
  if (opts.depth) query.depth = opts.depth;
  if (opts.limit) query.limit = opts.limit;
  if (opts.edgeTypeIds && opts.edgeTypeIds.length > 0) {
    query.edge_type_ids = opts.edgeTypeIds.join(",");
  }
  if (opts.entityTypeIds && opts.entityTypeIds.length > 0) {
    query.entity_type_ids = opts.entityTypeIds.join(",");
  }
  return api<NeighborhoodResponse>(`/entities/${seedId}/neighborhood`, {
    query,
  });
}


