import { api } from "./client";

export interface Entity {
  id: string;
  org_id: string;
  type_id: string;
  label: string;
  description: string;
  properties: Record<string, unknown>;
  embedding_id?: string;
  created_at: string;
  updated_at: string;
  legacy_id?: string;
}

export interface CreateEntityRequest {
  type_id: string;
  label: string;
  description?: string;
  properties?: Record<string, unknown>;
  corpus_ids?: string[];
}

export interface UpdateEntityRequest {
  label?: string;
  description?: string;
