/**
 * Turn one finished XHR into an ApiError.
 *
 * The upload path is the only place in this MFE that talks to the BFF without
 * going through `api()`, so it is also the only place that has to cope with a
 * response the platform envelope never produced. Two of those matter:
 *
 * - **nginx rejects the body itself.** An over-cap upload never reaches a BFF;
 *   nginx answers 413 with its own HTML error page. `JSON.parse` throws, and
 *   the previous code let the envelope stay `null` and fell through to the
 *   generic `upload failed: 413` — a string naming neither the file nor the
 *   reason, which is half of why an oversized upload looked like nothing
 *   happening at all (#2754).
 * - **any proxy hop 502s.** Same shape, different status.
 *
 * So the status is mapped to a code when the body can't supply one, and the
 * result is always an ApiError — structured, so callers branch on `status` /
 * `code` instead of matching English.
 */
function uploadFailure(status: number, responseText: string): ApiError {
  let envelope: { error?: { code?: string; message?: string } } | null = null;
  try {
    envelope = responseText ? JSON.parse(responseText) : null;
  } catch {
    // Not the platform envelope — an edge-generated HTML page, or a truncated
    // body. Fall through to the status-derived mapping below.
  }

  const fallbackCode =
    status === 413
      ? "request_too_large"
      : status >= 500
        ? "upstream_error"
        : "upload_failed";

  return new ApiError(
    status,
    envelope?.error?.code ?? fallbackCode,
    envelope?.error?.message ?? `upload failed: ${status}`,
  );
}

export async function uploadDocument(
  corpusId: string,
  file: File,
  opts: UploadOptions = {},
): Promise<UploadDocumentResponse> {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    const params = new URLSearchParams();
    if (opts.folderId) params.set("folder_id", opts.folderId);
    const qs = params.toString() ? `?${params.toString()}` : "";

    xhr.open("POST", `/api/v1/files/corpora/${corpusId}/documents${qs}`);
    xhr.withCredentials = true;
    xhr.setRequestHeader("Idempotency-Key", crypto.randomUUID());

    xhr.upload.onprogress = (e) => {
      if (e.lengthComputable && opts.onProgress) {
        opts.onProgress({ loaded: e.loaded, total: e.total });
      }
    };
    xhr.onload = () => {
      if (xhr.status >= 200 && xhr.status < 300) {
        let env: { data?: UploadDocumentResponse } | null = null;
        try {
          env = xhr.responseText ? JSON.parse(xhr.responseText) : null;
        } catch {
          // A 2xx we cannot parse is still a failure: there is no document id
          // to hand back, so resolving would report a phantom success.
        }
        if (env?.data) {
          resolve(env.data);
          return;
        }
      }
      reject(uploadFailure(xhr.status, xhr.responseText));
    };
    xhr.onerror = () =>
      reject(new ApiError(0, "network_error", "upload network error"));
    xhr.onabort = () => reject(new ApiError(0, "upload_aborted", "upload aborted"));
    opts.signal?.addEventListener("abort", () => xhr.abort());

    const fd = new FormData();
    fd.append("file", file);
    xhr.send(fd);
  });
}

export async function listDocuments(
  corpusId: string,
  opts: {
    limit?: number;
    cursor?: string;
    query?: string;
    /**
     * Folder filter. Omitted = corpus root only (`folder_id IS NULL`
     * on the server). Set to a folder id to scope the list to that
     * folder. The server has no "all folders" mode — to list every
     * document regardless of folder, call once per folder.
     */
    folderId?: string;
  } = {},
): Promise<ListDocumentsResponse> {
  const query: Record<string, string | number> = {};
  if (opts.limit) query.limit = opts.limit;
  if (opts.cursor) query.cursor = opts.cursor;
  if (opts.query) query.q = opts.query;
  if (opts.folderId) query.folder_id = opts.folderId;
  return api<ListDocumentsResponse>(`/corpora/${corpusId}/documents`, {
    query,
  });
}

