export async function purgeDocument(opts: {
  corpusId: string;
  docId: string;
}): Promise<PurgeResponse> {
  // Use raw fetch here so we can inspect the status before the api() helper
  // discards non-envelope 4xx responses. The 409 "would_orphan" path returns
  // a non-standard body { orphans: [...] } that must be preserved for
  // PurgeConfirmModal to read.
  const url = `/api/v1/files/corpora/${opts.corpusId}/documents/${opts.docId}:purge`;
  const res = await fetch(url, {
    method: "POST",
    credentials: "include",
    headers: {
      Accept: "application/json",
      "Idempotency-Key": crypto.randomUUID(),
    },
  });
  if (res.status === 409) {
    const body = (await res.json()) as { orphans?: unknown };
    const err = new Error("would_orphan") as Error & { orphans?: unknown };
    err.orphans = body.orphans;
    throw err;
  }
  if (!res.ok) {
    throw new Error(`purge failed: ${res.status}`);
  }
  const body = (await res.json()) as { data: PurgeResponse };
  return body.data;
}

export async function moveDocument(
  documentId: string,
  targetFolderId?: string,
): Promise<FilesDocument> {
