/**
 * Fetch the raw bytes of a document as a Blob.
 * Uses credentials:"include" (cookie auth, same as uploadDocument/purgeDocument).
 * Pass disposition:"attachment" to trigger a Content-Disposition: attachment header
 * on the server response (for browser download).
 */
export async function fetchDocumentBlob(
  documentId: string,
  disposition: "inline" | "attachment" = "inline",
): Promise<Blob> {
  const qs = disposition === "attachment" ? "?disposition=attachment" : "";
  const res = await fetch(`/api/v1/files/documents/${documentId}/raw${qs}`, {
    credentials: "include",
    headers: { Accept: "*/*" },
  });
  if (!res.ok) {
    throw new Error(`raw fetch failed: ${res.status}`);
  }
  return res.blob();
}


