  /** ISO 8601 timestamp. */
  timestamp: string;
  /** Audit event slug, e.g. "files.edge.added" or "audit.files.edge.added". */
  event_slug: string;
  /** Optional request id propagated from the original RPC headers. */
  request_id?: string;
}

