  audit_events: AuditEvent[];
}

interface AuditEntryEnvelope {
  event_id: string;
  action: string;
  actor: string;
  occurred_at: string;
  request_id?: string;
}

interface AuditEnvelope {
  entries: AuditEntryEnvelope[];
}

function adaptAuditEntries(env: AuditEnvelope): AuditEvent[] {
  return env.entries.map((e) => ({
    id: e.event_id,
    actor: e.actor,
    timestamp: e.occurred_at,
    event_slug: e.action,
    request_id: e.request_id,
  }));
}

